Add-Type -AssemblyName System.Drawing
$out=Split-Path -Parent $MyInvocation.MyCommand.Path;$c=Get-Content -Raw -Encoding UTF8 (Join-Path $out 'cat-reference-content.json')|ConvertFrom-Json
$font=New-Object System.Drawing.Font('Malgun Gothic',11);$small=New-Object System.Drawing.Font('Malgun Gothic',9);$label=New-Object System.Drawing.Font('Malgun Gothic',14,[System.Drawing.FontStyle]::Bold);$title=New-Object System.Drawing.Font('Malgun Gothic',30,[System.Drawing.FontStyle]::Bold);$ink=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(15,25,40));$green=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(238,250,239));$green2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(20,105,45),2);$orange=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,247,237));$orange2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(220,85,15),2);$blue=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(240,246,255));$blue2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(35,75,190),2);$purple=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(247,241,255));$purple2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(80,35,180),2);$gray=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(250,251,253));$gray2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(80,95,115),2);$line=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(30,35,45),2);$white=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
function B($g,$x,$y,$w,$h,$head,$body,$fill,$stroke){$g.FillRectangle($fill,$x,$y,$w,$h);$g.DrawRectangle($stroke,$x,$y,$w,$h);$s=[System.Drawing.StringFormat]::new();$s.Alignment='Center';$s.LineAlignment='Near';$g.DrawString($head,$label,$ink,[System.Drawing.RectangleF]::new($x+8,$y+12,$w-16,32),$s);$g.DrawString($body,$small,$ink,[System.Drawing.RectangleF]::new($x+12,$y+55,$w-24,$h-65),$s)}
function A($g,$x1,$y1,$x2,$y2,$t=''){$g.DrawLine($line,$x1,$y1,$x2,$y2);$g.FillPolygon($ink,@([System.Drawing.Point]::new($x2,$y2),[System.Drawing.Point]::new($x2-10,$y2-5),[System.Drawing.Point]::new($x2-10,$y2+5)));if($t){$s=[System.Drawing.StringFormat]::new();$s.Alignment='Center';$g.DrawString($t,$small,$ink,[System.Drawing.RectangleF]::new(($x1+$x2)/2-75,($y1+$y2)/2-20,150,40),$s)}}
$w=2400;$h=1380;$b=New-Object System.Drawing.Bitmap($w,$h);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::White);$g.SmoothingMode='AntiAlias'
$g.DrawString($c.title,$title,$ink,340,22);$g.DrawString($c.subtitle,$font,$ink,805,70)
B $g 28 300 220 390 $c.userHead $c.userBody $gray $gray2;B $g 285 300 220 390 $c.frontHead $c.frontBody $green $green2;A $g 248 480 285 480 'input';A $g 285 560 248 560 'answer'
$g.DrawRectangle($green2,575,105,690,1040);$g.DrawString($c.serverHead,$label,$ink,770,125)
